INSERT INTO t_user_auto_login (
    user_id
    , auto_login_token
    , expire_dt
    , frst_reg_dt
    , last_mdf_dt
)
VALUES (
    #{userId}
    , #{token}
    , #{expireDt}
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
)
ON CONFLICT (user_id)
DO UPDATE SET
    auto_login_token = #{token}
    , expire_dt = #{expireDt}
    , last_mdf_dt = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')

